class MessageProviderFactory {
private:
    unordered_map<string, IMessageProvider*> providers;

public:
    void registerProvider(string type, IMessageProvider* provider) {
        providers[type] = provider;
    }

    IMessageProvider* getProvider(string type) {
        auto it = providers.find(type);
        if (it == providers.end()) {
            throw runtime_error("No provider for type: " + type);
        }
        return it->second;
    }
};

